<?php require_login(['admin']);$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=$pdo->prepare('INSERT INTO events(title,event_date,description,location) VALUES(?,?,?,?)');$s->execute([trim($_POST['title']),$_POST['event_date'],trim($_POST['description']),trim($_POST['location'])]);flash('success','Event added.');redirect('index.php?page=events');}if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM events WHERE id=?')->execute([(int)$_GET['delete']]);flash('success','Event deleted.');redirect('index.php?page=events');}$rows=$pdo->query('SELECT * FROM events ORDER BY event_date DESC')->fetchAll();?><div class="grid2"><section class="panel"><h2>Add Event</h2><form class="form-grid" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Title<input required name="title"></label><label>Date<input type="date" required name="event_date"></label><label>Location<input name="location"></label><label class="wide">Description<textarea name="description" rows="5"></textarea></label><button class="btn primary wide">Add Event</button></form></section><section class="panel"><h2>Upcoming / Past Events</h2><?php foreach($rows as $r):?><article class="event"><b><?=e($r['title'])?></b><span><?=e(date('d M Y',strtotime($r['event_date'])))?> · <?=e($r['location'])?></span><p><?=e($r['description'])?></p><a class="action danger-text" href="index.php?page=events&delete=<?=$r['id']?>">Delete</a></article><?php endforeach;?></section></div>
